mapper.select:
SELECT ib.board_no AS boardNo , ib.title AS title , u.user_name AS regUserName , DATE_FORMAT(ib.reg_date, '%Y-%m-%d') AS regDate , ib.hit AS hit , ib.thumb_file_no AS thumbFileNo FROM image_board ib JOIN users u ON ib.reg_user = u.user_no WHERE ib.use_yn = 'Y'
AND ( ib.title LIKE CONCAT('%', #{searchKeyword}, '%') OR u.user_name LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY ib.board_no DESC LIMIT #{firstIndex}, #{recordCountPerPage}

mapper.update:
UPDATE image_board
SET    title         = #{title}
     , content       = #{content}
     , thumb_file_no = #{thumbFileNo}
     , mod_date      = NOW()
     , mod_user      = #{modUser}
WHERE  board_no = #{boardNo}

UPDATE image_board
SET    use_yn   = 'N'
     , mod_date = NOW()
     , mod_user = #{modUser}
WHERE  board_no = #{boardNo}

UPDATE image_board
SET    hit = hit + 1
WHERE  board_no = #{boardNo}

UPDATE file_master
SET    use_yn = 'N'
WHERE  file_no = #{fileNo}
